const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let input = [];
rl.on('line', (line) => {
    input.push(line);
}).on('close', () => {
    const [a, ta] = input[0].split(' ').map(Number);
    const [b, tb] = input[1].split(' ').map(Number);
    const departureTime = input[2];

    const [h, m] = departureTime.split(':').map(Number);
    const simionStart = h * 60 + m;
    const simionEnd = simionStart + ta;

    let count = 0;

    // Buses departing from B before Simion arrives at B
    // Bus departs B at time t, arrives at A at t + tb
    // Simion departs A at simionStart, arrives at B at simionEnd
    // They meet if the bus departs B before simionEnd and arrives at A after simionStart
    // So bus departure time t must satisfy: t < simionEnd and t + tb > simionStart
    // => t > simionStart - tb and t < simionEnd

    // First bus from B is at 05:00 (300 minutes)
    // Last bus from B departs at 23:59 (1439 minutes)

    // Calculate the earliest and latest bus departure times from B that Simion could meet
    const earliestBusB = Math.max(300, simionStart - tb + 1);
    const latestBusB = Math.min(1439, simionEnd - 1);

    if (earliestBusB <= latestBusB) {
        // Count buses from B that depart in [earliestBusB, latestBusB]
        // Buses depart every b minutes starting from 05:00 (300)
        // First bus >= earliestBusB
        let firstBus = 300 + Math.ceil((earliestBusB - 300) / b) * b;
        if (firstBus < earliestBusB) {
            firstBus += b;
        }

        // Last bus <= latestBusB
        let lastBus = 300 + Math.floor((latestBusB - 300) / b) * b;

        if (firstBus <= lastBus) {
            count = Math.floor((lastBus - firstBus) / b) + 1;
        }
    }

    console.log(count);
});
